    discount_bp = max(Fraction(0), min(Fraction(10000), discount_bp))
    value = price * quantity * (Fraction(10000) - discount_bp) / 10000
    rounded = _round_nonnegative(value, mode)
    return -rounded if event.get('kind') == 'refund' else rounded
